// Command is gimble run research-document: Gimble's environment flag, a flag for each field of Params, a
// model flag for each role ResearchDocument names with defaults supplied by the caller,
// the web application's flags, and a run of ResearchDocument on the runtime.
func Command(defaults map[gimble.WorkflowRole]string) *cobra.Command {
	var params Params
	var optMinSourcesPerTopic int
	var optMaxEditorialRounds int
	var researchPlanningModel string
	var researchIndexingModel string
	var documentSupervisionModel string
	var indexCurationModel string
	var documentAuthoringModel string
	var editorialReviewModel string
	var workDir string
	var port int
	var uds string
	var noWeb bool
	cmd := &cobra.Command{
		Use:   "research-document",
		Short: "ResearchDocument produces a research-backed document within a token budget.",
		Long:  "Package researchdocument researches a subject into a local semantic index,\nwrites a size-bounded document, and revises it until an independent editor\nfinds only nitpicks.\n\nThe planner returns exactly five coherent groups of adjacent or related\ntopics, one for each explicitly named parallel researcher. Each topic must\nleave at least the requested number of useful local source files, address\nevery assigned question or mark it unresolved, and write an INDEX.md that\ncites those sources and links to longer clips when compression would lose\nimportant detail. The index is a means to the document, not a completeness\nproject.\n\nThe author uses the combined semantic index as its entry point to the corpus.\nAn editorial pass checks the document against the goal, index, and token\nbudget. Material omissions trigger targeted research and index repair before\nanother revision. The workflow succeeds when the document is within budget\nand the editor reports only nitpicks, or returns an error after the editorial\nround limit.\n\nModel cost guidance: the configured defaults reserve Astra for\ndocument-authoring and editorial-review; research, indexing, curation, and\nsupervision already use Luna. Keep Astra for ambiguous, contested,\nhigh-stakes, or technically difficult synthesis. For a clearly bounded,\nroutine document, deliberately tune those two roles down to Sol or Opus:\n\n\t--document-authoring gpt-5.6-sol:high \\\n\t--editorial-review claude-opus-5:high\n\nFor low-risk background research where elapsed time and rejected editorial\ndrafts are cheap, another profile spends one frontier turn on the plan and\nuses Terra and Sonnet for the repeated writing and review:\n\n\t--research-planning gpt-6-astra:high \\\n\t--document-authoring gpt-5.6-terra:high \\\n\t--editorial-review claude-sonnet-5:high\n\nMaterial editorial failures can trigger another bounded revision. Provider,\nharness, and execution errors still end the run rather than retrying.\n\nExample:\n\n\tgimble run research-document \\\n\t  --goal \"Explain passkeys to security-conscious product managers\" \\\n\t  --research-dir ./passkeys-research \\\n\t  --output ./passkeys.md \\\n\t  --token-budget 4000",
		Args:  cobra.NoArgs,
	}
	cmd.Flags().StringVar(&params.Goal, "goal", "", "Goal describes the audience, subject, and understanding the document must produce. (required)")
	cmd.Flags().StringVar(&params.ResearchDir, "research-dir", "", "ResearchDir receives downloaded sources, clips, topic indexes, and the combined INDEX.md. (required)")
	cmd.Flags().StringVar(&params.Output, "output", "", "Output is the document file the author creates or revises. (required)")
	cmd.Flags().IntVar(&params.TokenBudget, "token-budget", 0, "TokenBudget is the maximum o200k_base token count accepted for the document. (required)")
	cmd.Flags().IntVar(&optMinSourcesPerTopic, "min-sources-per-topic", 0, "MinSourcesPerTopic overrides the default minimum of three useful local source files per planned topic.")
	cmd.Flags().IntVar(&optMaxEditorialRounds, "max-editorial-rounds", 0, "MaxEditorialRounds overrides the default limit of three editorial passes.")
	_ = cmd.MarkFlagRequired("goal")
	_ = cmd.MarkFlagRequired("research-dir")
	_ = cmd.MarkFlagRequired("output")
	_ = cmd.MarkFlagRequired("token-budget")
	cmd.Flags().StringVar(&workDir, "work-dir", ".", "the working directory for this run")
	researchPlanningModelDefault := defaults[gimble.WorkflowRole("research-planning")]
	if researchPlanningModelDefault == "" {
		cmd.Flags().StringVar(&researchPlanningModel, "research-planning", "", "the model for role research-planning, as model or model:effort")
		_ = cmd.MarkFlagRequired("research-planning")
	} else {
		cmd.Flags().StringVar(&researchPlanningModel, "research-planning", researchPlanningModelDefault, "advanced override for role research-planning, as model or model:effort; omit this flag to use the displayed workflow default")
	}
	researchIndexingModelDefault := defaults[gimble.WorkflowRole("research-indexing")]
	if researchIndexingModelDefault == "" {
		cmd.Flags().StringVar(&researchIndexingModel, "research-indexing", "", "the model for role research-indexing, as model or model:effort")
		_ = cmd.MarkFlagRequired("research-indexing")
	} else {
		cmd.Flags().StringVar(&researchIndexingModel, "research-indexing", researchIndexingModelDefault, "advanced override for role research-indexing, as model or model:effort; omit this flag to use the displayed workflow default")
	}
	documentSupervisionModelDefault := defaults[gimble.WorkflowRole("document-supervision")]
	if documentSupervisionModelDefault == "" {
		cmd.Flags().StringVar(&documentSupervisionModel, "document-supervision", "", "the model for role document-supervision, as model or model:effort")
		_ = cmd.MarkFlagRequired("document-supervision")
	} else {
		cmd.Flags().StringVar(&documentSupervisionModel, "document-supervision", documentSupervisionModelDefault, "advanced override for role document-supervision, as model or model:effort; omit this flag to use the displayed workflow default")
	}
	indexCurationModelDefault := defaults[gimble.WorkflowRole("index-curation")]
	if indexCurationModelDefault == "" {
		cmd.Flags().StringVar(&indexCurationModel, "index-curation", "", "the model for role index-curation, as model or model:effort")
		_ = cmd.MarkFlagRequired("index-curation")
	} else {
		cmd.Flags().StringVar(&indexCurationModel, "index-curation", indexCurationModelDefault, "advanced override for role index-curation, as model or model:effort; omit this flag to use the displayed workflow default")
	}
	documentAuthoringModelDefault := defaults[gimble.WorkflowRole("document-authoring")]
	if documentAuthoringModelDefault == "" {
		cmd.Flags().StringVar(&documentAuthoringModel, "document-authoring", "", "the model for role document-authoring, as model or model:effort")
		_ = cmd.MarkFlagRequired("document-authoring")
	} else {
		cmd.Flags().StringVar(&documentAuthoringModel, "document-authoring", documentAuthoringModelDefault, "advanced override for role document-authoring, as model or model:effort; omit this flag to use the displayed workflow default")
	}
	editorialReviewModelDefault := defaults[gimble.WorkflowRole("editorial-review")]
	if editorialReviewModelDefault == "" {
		cmd.Flags().StringVar(&editorialReviewModel, "editorial-review", "", "the model for role editorial-review, as model or model:effort")
		_ = cmd.MarkFlagRequired("editorial-review")
	} else {
		cmd.Flags().StringVar(&editorialReviewModel, "editorial-review", editorialReviewModelDefault, "advanced override for role editorial-review, as model or model:effort; omit this flag to use the displayed workflow default")
	}
	cmd.Flags().IntVar(&port, "port", 8080, "loopback TCP port for the web application")
	cmd.Flags().StringVar(&uds, "uds", "", "Unix-domain socket for the web application instead of TCP")
	cmd.Flags().BoolVar(&noWeb, "no-web", false, "run without the web application")
	cmd.RunE = func(cmd *cobra.Command, _ []string) error {
		if cmd.Flags().Changed("min-sources-per-topic") {
			params.MinSourcesPerTopic = polytype.Optional[int]{Present: true, Value: optMinSourcesPerTopic}
		}
		if cmd.Flags().Changed("max-editorial-rounds") {
			params.MaxEditorialRounds = polytype.Optional[int]{Present: true, Value: optMaxEditorialRounds}
		}
		workDir, err := filepath.Abs(workDir)
		if err != nil {
			return err
		}
		models, err := binding.Roles(map[gimble.WorkflowRole]string{gimble.WorkflowRole("research-planning"): researchPlanningModel, gimble.WorkflowRole("research-indexing"): researchIndexingModel, gimble.WorkflowRole("document-supervision"): documentSupervisionModel, gimble.WorkflowRole("index-curation"): indexCurationModel, gimble.WorkflowRole("document-authoring"): documentAuthoringModel, gimble.WorkflowRole("editorial-review"): editorialReviewModel})
		if err != nil {
			return err
		}
		ctx, stop := signal.NotifyContext(cmd.Context(), os.Interrupt)
		defer stop()
		var options []web.Option
		switch {
		case noWeb:
			options = append(options, web.WithNoWeb())
		case uds != "":
			options = append(options, web.WithUDS(uds))
		default:
			options = append(options, web.WithPort(port))
		}
		runtime, err := web.NewRuntime(ctx, filepath.Join(workDir, ".gimble"), options...)
		if err != nil {
			return err
		}
		env := gimble.Env{WorkDir: workDir}
		return runtime.Run(ctx, "research-document", models, func(ctx context.Context) error { return ResearchDocument(ctx, env, params) })
	}
	return cmd
}
